.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
}

.stat {
  background: #f8f9fd;
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 14px;
}

.stat strong {
  display: block;
  font-size: 28px;
}

@media (max-width: 640px) {
  .nav {
    align-items: flex-start;
  }

  .nav-links {
    width: 100%;
  }

  button, .button {
    width: 100%;
  }

  .inline-form {
    display: block;
    width: 100%;
  }

  .actions {
    width: 100%;
  }
}

