              <th>Prazo</th>
              <th>Status</th>
              <th>Ação</th>
            </tr>
          </thead>
          <tbody>
            <% loans.forEach(loan => { %>
              <tr>
                <td>
                  <strong><%= loan.user_name %></strong><br>
                  <span class="muted"><%= loan.user_email %></span><br>
                  <% if (loan.blocked) { %>
                    <span class="badge danger">Bloqueado para novos empréstimos</span>
                  <% } %>
                </td>
                <td>
                  <strong><%= loan.item_title %></strong><br>
                  <span class="muted"><%= loan.item_author || '' %></span>
                </td>
                <td><%= loan.borrowed_at %></td>
                <td><%= loan.due_at %></td>
                <td>
                  <% if (loan.returned_at) { %>
                    <span class="badge success">Devolvido</span><br>
                    <span class="muted"><%= loan.returned_at %></span>
                  <% } else if (loan.overdue) { %>
                    <span class="badge danger">Em atraso</span>
                  <% } else { %>
                    <span class="badge warning">Emprestado</span>
                  <% } %>
                </td>
                <td>
                  <% if (!loan.returned_at) { %>
                    <form action="/loans/<%= loan.id %>/return" method="post">
                      <button type="submit">Registrar devolução</button>
                    </form>
                  <% } else { %>
                    -
                  <% } %>
                </td>
              </tr>
            <% }) %>
          </tbody>
        </table>
      <% } %>
    </section>
  </main>
</body>
</html>

